package solution

import (
	"reflect"
	"sort"
	"testing"
)

func TestStockLedgerConstructionSnapshotAndInputCopy(t *testing.T) {
	initial := map[string]int{"SKU_2": 3, "SKU-1": 7}
	ledger, err := NewStockLedger(initial)
	if err != nil {
		t.Fatal(err)
	}
	initial["SKU_2"] = 100
	initial["new"] = 4

	want := []StockItem{{SKU: "SKU-1", Quantity: 7}, {SKU: "SKU_2", Quantity: 3}}
	if got := ledger.Snapshot(); !reflect.DeepEqual(got, want) {
		t.Fatalf("Snapshot() = %#v, want %#v", got, want)
	}
	if _, ok := ledger.Quantity("new"); ok {
		t.Fatal("ledger retained the initial map")
	}
}

func TestStockLedgerConstructionErrorsAndEmptySnapshot(t *testing.T) {
	for _, sku := range []string{"", "bad sku", "é", "slash/name"} {
		if ledger, err := NewStockLedger(map[string]int{sku: 0}); ledger != nil || err != ErrInvalidSKU {
			t.Errorf("NewStockLedger(%q) = %#v, %v", sku, ledger, err)
		}
	}
	if ledger, err := NewStockLedger(map[string]int{"valid": -1}); ledger != nil || err != ErrInsufficientStock {
		t.Fatalf("negative initial quantity = %#v, %v", ledger, err)
	}
	ledger, err := NewStockLedger(nil)
	if err != nil {
		t.Fatal(err)
	}
	if got := ledger.Snapshot(); got == nil || len(got) != 0 {
		t.Fatalf("empty Snapshot() = %#v", got)
	}
}

func TestStockLedgerApplyIsAtomic(t *testing.T) {
	ledger, err := NewStockLedger(map[string]int{"A": 5, "B": 2})
	if err != nil {
		t.Fatal(err)
	}
	changes := map[string]int{"A": -3, "B": 4, "C": 1}
	if err := ledger.Apply(changes); err != nil {
		t.Fatal(err)
	}
	changes["A"] = 100
	for sku, want := range map[string]int{"A": 2, "B": 6, "C": 1} {
		if got, ok := ledger.Quantity(sku); !ok || got != want {
			t.Errorf("Quantity(%q) = %d, %v; want %d, true", sku, got, ok, want)
		}
	}

	before := ledger.Snapshot()
	if err := ledger.Apply(map[string]int{"A": 1, "B": -7}); err != ErrInsufficientStock {
		t.Fatalf("insufficient Apply error = %v", err)
	}
	if got := ledger.Snapshot(); !reflect.DeepEqual(got, before) {
		t.Fatalf("failed Apply partially mutated ledger: %#v", got)
	}
	if err := ledger.Apply(map[string]int{"A": 1, "bad sku": 1}); err != ErrInvalidSKU {
		t.Fatalf("invalid Apply error = %v", err)
	}
	if got := ledger.Snapshot(); !reflect.DeepEqual(got, before) {
		t.Fatalf("invalid Apply partially mutated ledger: %#v", got)
	}
}

func TestStockLedgerZeroDeltaRecordsMissingSKUAndSortsBytewise(t *testing.T) {
	ledger, _ := NewStockLedger(nil)
	if err := ledger.Apply(map[string]int{"z": 0, "A": 0, "a": 0}); err != nil {
		t.Fatal(err)
	}
	got := ledger.Snapshot()
	wantNames := []string{"A", "a", "z"}
	if len(got) != len(wantNames) {
		t.Fatalf("Snapshot() = %#v", got)
	}
	for index, name := range wantNames {
		if got[index] != (StockItem{SKU: name, Quantity: 0}) {
			t.Errorf("entry %d = %#v", index, got[index])
		}
	}
	if !sort.SliceIsSorted(got, func(a, b int) bool { return got[a].SKU < got[b].SKU }) {
		t.Fatal("snapshot is not sorted")
	}
}

package solution

import (
	"os"
	"os/exec"
	"testing"
)

// Re-run the unmodified original tests in fresh processes to expose dependence
// on Go's unspecified map iteration order. This is a diagnostic, not admission.
func TestReviewStockDirectionalityRepeatability(t *testing.T) {
	passed := 0
	for i := 0; i < 64; i++ {
		cmd := exec.Command(os.Args[0], "-test.run=^TestStockLedger", "-test.count=1")
		output, err := cmd.CombinedOutput()
		if err == nil {
			passed++
		} else if _, ok := err.(*exec.ExitError); !ok {
			t.Fatalf("child infrastructure error: %v; %s", err, output)
		}
	}
	// Always emit counts, including on a passing reference control.
	t.Errorf("DIAGNOSTIC_ONLY: original-suite passes=%d failures=%d trials=64", passed, 64-passed)
}

